def _check(name: str, cond: bool) -> None:
    status = "ok  " if cond else "FAIL"
    print(f"  [{status}] {name}")
    if not cond:
        _FAILS.append(name)

def _check(name: str, cond: bool) -> None:
    global _failures
    status = "ok" if cond else "FAILED"
    if not cond:
        _failures += 1
    print(f"  {status}: {name}")

def _check(name: str, cond: bool, detail: str = "") -> None:
    status = "ok  " if cond else "FAIL"
    line = f"  [{status}] {name}"
    if detail:
        line += f" — {detail}"
    print(line)
    if not cond:
        _FAILS.append(name)
